def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def components(value_test):
        seen = set()
        result = []
        for r in range(h):
            for c in range(w):
                if (r, c) in seen or not value_test(grid[r][c]):
                    continue
                stack = [(r, c)]
                seen.add((r, c))
                comp = set()
                while stack:
                    y, x = stack.pop()
                    comp.add((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        q = (y + dy, x + dx)
                        if (0 <= q[0] < h and 0 <= q[1] < w
                                and q not in seen and value_test(grid[q[0]][q[1]])):
                            seen.add(q)
                            stack.append(q)
                result.append(comp)
        return result

    lines = components(lambda v: v == 5)
    patterns = components(lambda v: v != 0 and v != 5)

    for line in lines:
        rs = [r for r, c in line]
        cs = [c for r, c in line]
        rmin, rmax = min(rs), max(rs)
        cmin, cmax = min(cs), max(cs)

        if cmin == cmax and rmin < rmax:
            vertical = True
        elif rmin == rmax and cmin < cmax:
            vertical = False
        else:
            continue

        for pat in patterns:
            if not any(
                (r + dr, c + dc) in line
                for r, c in pat
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))
            ):
                continue

            prs = [r for r, c in pat]
            pcs = [c for r, c in pat]
            pminr, pmaxr = min(prs), max(prs)
            pminc, pmaxc = min(pcs), max(pcs)

            if vertical:
                # Align the pattern's end with the nearest end of the 5-line.
                use_max = abs(pmaxr - rmax) <= abs(pminr - rmin)
                for r in range(rmin, rmax + 1):
                    if use_max:
                        sr = pmaxr - ((rmax - r) % (pmaxr - pminr + 1))
                    else:
                        sr = pminr + ((r - rmin) % (pmaxr - pminr + 1))
                    for c in range(pminc, pmaxc + 1):
                        if (sr, c) in pat:
                            out[r][c] = grid[sr][c]
            else:
                use_max = abs(pmaxc - cmax) <= abs(pminc - cmin)
                for c in range(cmin, cmax + 1):
                    if use_max:
                        sc = pmaxc - ((cmax - c) % (pmaxc - pminc + 1))
                    else:
                        sc = pminc + ((c - cmin) % (pmaxc - pminc + 1))
                    for r in range(pminr, pmaxr + 1):
                        if (r, sc) in pat:
                            out[r][c] = grid[r][sc]

    return out
